<?php
// SkillGraph PHP/MySQL edition — same API routes and JSON contract as the React client.
declare(strict_types=1);
header('Content-Type: application/json; charset=utf-8');
header('X-Content-Type-Options: nosniff');
header('Cache-Control: no-store');
function fail(int $status,string $message): never { http_response_code($status);echo json_encode(['detail'=>$message],JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE);exit; }
function jsonBody(): array { $v=json_decode(file_get_contents('php://input'),true);return is_array($v)?$v:[]; }
function b64u(string $v): string { return rtrim(strtr(base64_encode($v),'+/','-_'),'='); }
function tokenFor(int $uid): string { global $cfg;$h=b64u(json_encode(['alg'=>'HS256','typ'=>'JWT']));$p=b64u(json_encode(['sub'=>(string)$uid,'exp'=>time()+604800]));return $h.'.'.$p.'.'.b64u(hash_hmac('sha256',$h.'.'.$p,$cfg['jwt_secret'],true)); }
function currentUser(): int { global $pdo,$cfg;$auth=$_SERVER['HTTP_AUTHORIZATION']??'';if($auth===''&&function_exists('getallheaders')){$headers=getallheaders();$auth=$headers['Authorization']??$headers['authorization']??'';}if(!preg_match('/^Bearer\s+([\w.-]+)$/',$auth,$m))fail(401,'Sign in to continue');$parts=explode('.',$m[1]);if(count($parts)!==3)fail(401,'Session expired');$payload=json_decode(base64_decode(strtr($parts[1],'-_','+/')),true);$sig=b64u(hash_hmac('sha256',$parts[0].'.'.$parts[1],$cfg['jwt_secret'],true));if(!is_array($payload)||!hash_equals($sig,$parts[2])||(int)($payload['exp']??0)<time())fail(401,'Session expired');$uid=(int)($payload['sub']??0);if(!row('SELECT id FROM users WHERE id=?',[$uid]))fail(401,'User not found');return $uid; }
function aiEnabled(): bool { global $cfg;return in_array(strtolower((string)($cfg['ai_provider']??'')),['openai','openai_compatible'],true)&&!empty($cfg['ai_api_key'])&&function_exists('curl_init'); }
function aiCall(string $system,array $payload): ?array { global $cfg;if(!aiEnabled())return null;$url=rtrim((string)($cfg['ai_base_url']??'https://api.openai.com/v1'),'/').'/chat/completions';$body=json_encode(['model'=>$cfg['ai_model']??'gpt-4o-mini','response_format'=>['type'=>'json_object'],'temperature'=>0,'messages'=>[['role'=>'system','content'=>$system],['role'=>'user','content'=>json_encode($payload,JSON_UNESCAPED_UNICODE)]]]);$c=curl_init($url);curl_setopt_array($c,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$cfg['ai_api_key'],'Content-Type: application/json'],CURLOPT_POSTFIELDS=>$body,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_TIMEOUT=>20]);$raw=curl_exec($c);$status=(int)curl_getinfo($c,CURLINFO_HTTP_CODE);curl_close($c);if(!is_string($raw)||$status<200||$status>=300)return null;$outer=json_decode($raw,true);$content=$outer['choices'][0]['message']['content']??null;if(!is_string($content))return null;$result=json_decode($content,true);return is_array($result)?$result:null; }
function normalizeLlm(string $phrase): ?string { $names=array_column(catalog(),'name');$result=aiCall('Map the supplied skill phrase to exact canonical catalogue name(s) only. Omit uncertain or unsupported phrases. Return JSON object with skills array.', ['skill_names'=>[$phrase],'catalog'=>$names]);if(!$result||!is_array($result['skills']??null))return null;foreach($result['skills'] as $name)if(is_string($name)&&in_array($name,$names,true))return $name;return null; }
function rows(string $sql,array $args=[]): array { global $pdo;$s=$pdo->prepare($sql);$s->execute($args);return $s->fetchAll(PDO::FETCH_ASSOC); }
function row(string $sql,array $args=[]): ?array { return rows($sql,$args)[0]??null; }
function run(string $sql,array $args=[]): PDOStatement { global $pdo;$s=$pdo->prepare($sql);$s->execute($args);return $s; }
function profile(int $uid): array { $u=row('SELECT u.id,u.email,u.name,u.role_id AS target_role_id,p.education,p.experience AS experience_years,p.interests FROM users u LEFT JOIN profiles p ON p.user_id=u.id WHERE u.id=?',[$uid]);if(!$u)fail(401,'User not found');$u['id']=(int)$u['id'];$u['target_role_id']=$u['target_role_id']===null?null:(int)$u['target_role_id'];$u['experience_years']=(int)($u['experience_years']??0);$u['skills']=rows('SELECT s.name AS skill,us.level,us.evidence FROM user_skills us JOIN skills s ON s.id=us.skill_id WHERE us.user_id=? ORDER BY s.name',[$uid]);foreach($u['skills'] as &$x)$x['level']=(int)$x['level'];return $u; }
function roleRow(int $id): ?array { $r=row('SELECT id,name,family,summary FROM roles WHERE id=?',[$id]);if($r)$r['id']=(int)$r['id'];return $r; }
function catalog(bool $public=false): array { $s=rows('SELECT id,name,category,aliases,description FROM skills ORDER BY name');foreach($s as &$x){$x['id']=(int)$x['id'];if($public)unset($x['aliases']);}return $s; }
function findSkill(string $input): ?array { $needle=mb_strtolower(trim($input));foreach(catalog() as $s)foreach(array_merge([$s['name']],explode('|',$s['aliases'])) as $term){$term=mb_strtolower(trim($term));if($term!==''&&preg_match('/(?<![a-z0-9])'.preg_quote($term,'/').'(?![a-z0-9])/u',$needle))return $s;}return null; }
function roleList(): array { $r=rows('SELECT r.id,r.name,r.family,r.summary,(SELECT COUNT(*) FROM requirements q WHERE q.role_id=r.id) AS skill_count FROM roles r ORDER BY r.name');foreach($r as &$x){$x['id']=(int)$x['id'];$x['skill_count']=(int)$x['skill_count'];}return $r; }
function scoreRole(int $rid,array $items): array { $req=rows('SELECT s.name AS skill,r.weight,r.expected FROM requirements r JOIN skills s ON s.id=r.skill_id WHERE r.role_id=?',[$rid]);$by=[];foreach($items as $x)$by[mb_strtolower($x['skill'])]=$x;$factor=['assessed'=>1.0,'project_supported'=>1.0,'self_reported'=>.8,'resume_derived'=>.55];$total=0;$earned=0;$gaps=[];foreach($req as $r){$r['weight']=(float)$r['weight'];$r['expected']=(int)$r['expected'];$total+=$r['weight'];$got=$by[mb_strtolower($r['skill'])]??null;$level=(int)($got['level']??0);$conf=$got?($factor[$got['evidence']]??.6):1;$earned+=$r['weight']*min($level/$r['expected'],1)*$conf;if($level<$r['expected'])$gaps[]=['skill'=>$r['skill'],'level'=>$level,'expected_level'=>$r['expected'],'importance'=>$r['weight'],'gap'=>$r['expected']-$level,'evidence'=>$got['evidence']??null,'confidence'=>$conf];}$impact=[];foreach(rows('SELECT c.name AS child,p.name AS parent FROM dependencies d JOIN skills c ON c.id=d.skill_id JOIN skills p ON p.id=d.prerequisite_id') as $d)$impact[$d['parent']]=($impact[$d['parent']]??0)+1;usort($gaps,fn($a,$b)=>($b['importance']*$b['gap']+($impact[$b['skill']]??0)*.5)<=>($a['importance']*$a['gap']+($impact[$a['skill']]??0)*.5));return ['score'=>(int)round(100*$earned/($total?:1)),'gaps'=>$gaps]; }
function analysis(int $uid,?int $rid=null,bool $save=false): array { $p=profile($uid);$rid=$rid?:$p['target_role_id'];if(!$rid)fail(400,'Choose a target role first');$r=roleRow($rid);if(!$r)fail(404,'Role not found');$o=scoreRole($rid,$p['skills']);$top=array_slice(array_column($o['gaps'],'skill'),0,3);$explanation=$top?'Focus first on '.implode(', ',$top).'. These items rank highest by role weight, remaining proficiency gap, and prerequisite impact.':'Your listed skills currently meet the curated starter requirements for this role.';$mode='rule_based';$ai=aiCall('Write a concise supportive explanation of these role skill gaps, using supplied data only. Do not claim job-market demand or employment outcomes. Return JSON object with explanation string.', ['role'=>$r['name'],'gaps'=>array_slice($o['gaps'],0,8),'experience_years'=>$p['experience_years']]);if(is_string($ai['explanation']??null)&&trim($ai['explanation'])!==''&&strlen($ai['explanation'])<=1200){$explanation=$ai['explanation'];$mode='llm';}$o+=['role'=>['id'=>$r['id'],'name'=>$r['name']],'rubric'=>'Curated starter requirements. Progress score, not employment probability.','explanation'=>$explanation,'explanation_mode'=>$mode];if($save)run('INSERT INTO history(user_id,role_id,score,created) VALUES(?,?,?,?)',[$uid,$rid,$o['score'],gmdate('c')]);return $o; }
function roadmap(int $uid): array { $a=analysis($uid);$urls=['Python'=>'https://docs.python.org/3/tutorial/','SQL'=>'https://www.postgresql.org/docs/current/tutorial.html','Machine Learning'=>'https://scikit-learn.org/stable/user_guide.html','FastAPI'=>'https://fastapi.tiangolo.com/tutorial/','React'=>'https://react.dev/learn','TypeScript'=>'https://www.typescriptlang.org/docs/','Docker'=>'https://docs.docker.com/get-started/','Statistics'=>'https://www.openintro.org/book/os/'];$out=[];foreach($a['gaps'] as $i=>$g){$s=row('SELECT id FROM skills WHERE name=?',[$g['skill']]);$q=row('SELECT id,status FROM roadmap WHERE user_id=? AND skill_id=?',[$uid,$s['id']]);if(!$q){run("INSERT INTO roadmap(user_id,skill_id,status) VALUES(?,?,'not_started')",[$uid,$s['id']]);$q=['id'=>(int)$GLOBALS['pdo']->lastInsertId(),'status'=>'not_started'];}$pre=array_column(rows('SELECT p.name FROM dependencies d JOIN skills p ON p.id=d.prerequisite_id WHERE d.skill_id=?',[$s['id']]),'name');$out[]=['id'=>(int)$q['id'],'skill'=>$g['skill'],'priority'=>$i+1,'rationale'=>'Ordered by role importance, remaining gap, and prerequisite impact.','prerequisites'=>$pre,'resource'=>$urls[$g['skill']]??'https://developers.google.com/machine-learning/crash-course','exercise'=>'Build a small '.$g['skill'].' example for your target role.','completion_criteria'=>'Complete the exercise and explain your approach.','effort_hours'=>max(4,$g['gap']*8),'status'=>$q['status']];}return ['items'=>$out,'role'=>$a['role']]; }
function graphData(int $uid,?int $rid=null): array { $a=analysis($uid,$rid,false);$rid=$a['role']['id'];$req=rows('SELECT s.name FROM requirements r JOIN skills s ON s.id=r.skill_id WHERE r.role_id=?',[$rid]);$have=profile($uid)['skills'];$by=[];foreach($have as $x)$by[$x['skill']]=$x;$names=array_unique(array_merge(array_column($a['gaps'],'skill'),array_keys($by),array_column($req,'name')));$nodes=[];foreach(catalog() as $s)if(in_array($s['name'],$names,true)){$h=$by[$s['name']]??null;$nodes[]=['id'=>$s['name'],'data'=>['label'=>$s['name'],'description'=>$s['description'],'level'=>$h?(int)$h['level']:0,'evidence'=>$h['evidence']??null,'status'=>$h&&(int)$h['level']>=2?'developed':'gap'],'position'=>['x'=>0,'y'=>0]];}$nodes[]=['id'=>'role-'.$rid,'data'=>['label'=>$a['role']['name']],'position'=>['x'=>0,'y'=>0]];$edges=[];foreach(rows('SELECT c.name AS child,p.name AS parent FROM dependencies d JOIN skills c ON c.id=d.skill_id JOIN skills p ON p.id=d.prerequisite_id') as $d)if(in_array($d['child'],$names,true)&&in_array($d['parent'],$names,true))$edges[]=['id'=>$d['parent'].'-'.$d['child'],'source'=>$d['parent'],'target'=>$d['child']];foreach($req as $i=>$s)$edges[]=['id'=>($i+1).'-role','source'=>$s['name'],'target'=>'role-'.$rid];return ['nodes'=>$nodes,'edges'=>$edges,'role'=>$a['role']]; }
